"""Editable website policy copy matching this informational/enquiry website."""
def policies(ar):
    def t(a,e):return a if ar else e
    return {
      'terms':(t('شروط استخدام الموقع','Website terms'),t('معلومات تعريفية لبدء الحوار حول مشروعك، وعلاقتها بعرض السعر والعقد.','Information to start a project conversation, and its relationship to quotations and contracts.'),[
        (t('الغرض من الموقع','Purpose of this website'),t('يعرض الموقع خدمات KFATA ونماذج من أعمالها لتسهيل التعرف عليها وطلب التواصل. المعلومات والصور تعريفية، ولا تعد عرض سعر أو تعهدًا بتنفيذ نطاق أو مدة أو ضمان محدد.','This website introduces KFATA’s services and selected work and enables enquiries. Its information and images are descriptive and do not constitute a quotation or a commitment to a particular scope, schedule or guarantee.')),
        (t('عروض الأسعار والتعاقد','Quotations and contracts'),t('إرسال النموذج أو التواصل لا ينشئ عقدًا. تحدد الأعمال والأسعار والمدة والمسؤوليات والشروط في عرض سعر وعقد معتمدين بين الأطراف.','Submitting an enquiry or contacting us does not create a contract. Work, prices, schedule, responsibilities and terms are defined in an approved quotation and contract between the parties.')),
        (t('استخدام المحتوى والتواصل','Content and contact'),t('لا تنسب صور أعمال الموقع إلى أعمالك ولا تستخدم شعاراته أو مواده على نحو مضلل. للاستفسار عن إذن استخدام مادة أو تصحيح معلومة تواصل على info@kfata.com. الروابط الخارجية مثل الخريطة وواتساب تخضع لإعدادات وسياسات خدماتها.','Do not present project images as your work or use the site’s marks or material misleadingly. Contact info@kfata.com for permission requests or corrections. External services such as maps and WhatsApp have their own settings and policies.')),
      ]),
      'cookies':(t('ملفات الارتباط والتخزين الوظيفي','Cookies and functional storage'),t('ما يستخدمه الموقع للنماذج والجلسات وتفضيل الافتتاحية، دون تتبع إعلاني.','How the website supports forms, sessions and the opening animation, without advertising tracking.'),[
        (t('ملفات ضرورية','Necessary cookies'),t('قد يضع نموذج التواصل ملف csrftoken لحماية الإرسال من التزوير، بعمر افتراضي يقارب سنة. يستخدم sessionid عند الحاجة للجلسة ورسائل نجاح النموذج والدخول الإداري، بعمر افتراضي أسبوعين، ويمسح أو يتغير بحسب انتهاء الجلسة والدخول والخروج. يمكنك حذفها من إعدادات المتصفح؛ تعطيلها قد يمنع الإرسال أو الدخول.','The enquiry form may set csrftoken to protect submissions against forgery, with a default lifetime of approximately one year. sessionid supports sessions, form receipt messages and administration sign-in when needed, with a default lifetime of two weeks; it may be cleared or renewed through expiry and sign-in/out. You can delete these in browser settings; blocking them can prevent submissions or sign-in.')),
        (t('تخزين الجلسة والخيارات','Session storage and choices'),t('يحفظ sessionStorage علامة لعرض الافتتاحية مرة خلال الجلسة. لا ترسل هذه العلامة إلى الخادم. لا توجد حاليًا ملفات تتبع إعلاني أو تحليلات اختيارية، وتستضاف خطوط الموقع محليًا. لا يستخدم الموقع تتبعًا اختياريًا يستلزم شريط موافقة.','Session storage records whether the opening animation has been shown during the session. That flag is not sent to the server. No advertising trackers or optional visitor analytics are installed, and fonts are hosted locally. No optional tracking requiring a consent banner is enabled.')),
        (t('بيانات الطلبات','Enquiry data'),t('توضح سياسة الخصوصية بيانات النموذج والمرفقات والصلاحيات والاحتفاظ والحذف ووسيلة التواصل بشأن بياناتك.','The privacy notice explains enquiry data, attachments, access, retention, deletion and how to contact us about your data.')),
      ]),
    }
